      use: "pod ramieniem szafki narożnej",
      wariant: nozkaWariant(cab, geo.legH),
      spec: `pod ramieniem szafki narożnej, wysokość ${fmt(geo.legH)} mm: `
        + `${lp.us.length} pary — przy rogu, ${lp.us.length > 2 ? "na środku i " : ""}pod wolnym końcem`,
